export function authErrorMessage(error: unknown): string {
 const code = (error as {code?: string})?.code;
 const messages: Record<string,string> = {
  'auth/popup-closed-by-user': '로그인을 취소했습니다. 다시 선택해 주세요.',
  'auth/cancelled-popup-request': '진행 중인 로그인 창을 확인해 주세요.',
  'auth/popup-blocked': '팝업이 차단되었습니다. 이 사이트의 팝업을 허용해 주세요.',
  'auth/network-request-failed': '연결을 확인하고 다시 시도해 주세요.',
  'auth/unauthorized-domain': '이 주소에서 로그인할 수 없습니다. 관리자에게 문의해 주세요.',
  'auth/operation-not-allowed': '로그인이 아직 활성화되지 않았습니다. 관리자에게 문의해 주세요.',
  'auth/credential-already-in-use': '이미 다른 계정에 연결된 Google 계정입니다. 게스트 진행은 그대로 유지됩니다.',
  'auth/account-exists-with-different-credential': '이미 다른 로그인 방식으로 가입된 계정입니다.',
  'auth/too-many-requests': '요청이 많습니다. 잠시 후 다시 시도해 주세요.',
  'auth/web-storage-unsupported': '브라우저 저장소를 사용할 수 없습니다. 저장소 허용 후 다시 시도해 주세요.',
 };
 return (code && messages[code]) || '로그인하지 못했습니다. 잠시 후 다시 시도해 주세요.';
}
