export interface LobbySnapshot {online:Record<string,number>;plays:Record<string,number>;best:string|null;popular:string|null;updatedAt:number;}
export class LobbyPresence {
 snapshot:LobbySnapshot|null=null;private session='';private slot:string|null=null;private timer:any;private sequence=0;private alive=true;
 constructor(private changed:()=>void){this.session='pocket-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);void this.heartbeat();this.timer=setInterval(()=>void this.heartbeat(),15000);}
 private async post(route:string,body:object){try{const response=await fetch('/api/lobby/'+route,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({session:this.session,...body})});if(response.ok&&this.alive){this.snapshot=await response.json();this.changed();}}catch{if(this.alive){this.snapshot=null;this.changed();}}}
 enter(slot:string|null){this.slot=slot;void this.heartbeat();}
 private heartbeat(){return this.post('heartbeat',{slot:typeof document!=='undefined'&&document.hidden?null:this.slot});}
 play(){if(this.slot)void this.post('play',{slot:this.slot,round:this.session+'-'+(++this.sequence)});}
 dispose(){clearInterval(this.timer);void this.post('heartbeat',{slot:null});this.alive=false;}
}
