export interface SymbolSpec { id: string; name: string; color: string; weight: number; payout: number; art?:string; }
export interface SlotConfig { id: string; title: string; subtitle: string; tag: string; color: string; accent: string; description: string; symbols: SymbolSpec[]; }
export interface Win { line: number; symbol: string; amount: number; cells: number[]; multiplier?:number; }
export interface CellDrop { to:number; from:number; symbol:string; }
export interface Cascade { board: string[]; wins: Win[]; payout: number; multiplier: number; cellMultipliers:number[]; nextMultipliers:number[]; drops:CellDrop[]; removedCells?:number[]; }
export interface SpinResult { board: string[]; bet: number; payout: number; wins: Win[]; openingBoard?:string[];expandedCells?:number[];scatterAward?:Win;adjustment?:Win & {caption:string}; cascades?: Cascade[]; rounds?:SpinResult[]; roundLabel?:string;heldCells?:number[];symbolValues?:number[];featureText?:string;collectorCells?:number[];moneyCells?:number[];freeSpinsAwarded?:number;featureName?:string; }
export const PAYLINES = [[3,4,5],[0,1,2],[6,7,8],[0,4,8],[6,4,2]];
/** Common slot lifecycle. Presentation and wallet are intentionally separate. */
export abstract class SlotMain {
  abstract readonly config: SlotConfig;
  readonly columns: number = 3;
  readonly rows: number = 3;
  readonly mode: 'lines' | 'clusters' = 'lines';
  readonly paylines:number[][]=PAYLINES;
  readonly maxWin:number=5000;readonly hasBonus:boolean=false;get bonusSymbol():string|undefined{return undefined;}
  /** Prices in 0.1T units. Complex feature subclasses may override this getter. */
  get unlockPriceTenths():number{return this.mode==='clusters'?1000:this.columns>=5?500:300;}
  readonly bets = [10,25,50,100,250,500,1000,2500,5000,10000];
  protected pick(rng: () => number): string {
    const symbols = this.config.symbols;
    let roll = rng() * symbols.reduce((sum, s) => sum + s.weight, 0);
    for (const symbol of symbols) { roll -= symbol.weight; if (roll < 0) return symbol.id; }
    return symbols[symbols.length - 1].id;
  }
  spin(bet: number, rng: () => number = Math.random): SpinResult {
    if (!this.bets.includes(bet)) throw new Error('Invalid bet');
    const board = Array.from({length:9}, () => this.pick(rng));
    return this.evaluate(board, bet);
  }
  /** Clearly labelled, free presentation preview. Never used for paid spins. */
  demoSpin(bet:number):SpinResult {
    const [a,b,c]=this.config.symbols.map(s=>s.id);
    return this.evaluate([a,b,c,a,a,a,c,b,a],bet);
  }
  bonusDemoSpin(bet:number):SpinResult{let seed=20260918;const rng=()=>{seed^=seed<<13;seed^=seed>>>17;seed^=seed<<5;return(seed>>>0)/4294967296;};for(let i=0;i<10000;i++){const result=this.spin(bet,rng);if(result.rounds)return result;}return this.demoSpin(bet);}
  evaluate(board: string[], bet: number): SpinResult {
    if (board.length !== 9 || !this.bets.includes(bet) || board.some(id => !this.config.symbols.some(s => s.id === id))) throw new Error('Invalid spin');
    const wins: Win[] = [];
    PAYLINES.forEach((cells, line) => {
      const symbol = this.config.symbols.find(s => s.id === board[cells[0]])!;
      if (symbol.payout>0&&cells.every(i => board[i] === symbol.id)) wins.push({line, symbol:symbol.id, amount:symbol.payout * bet / PAYLINES.length, cells:[...cells]});
    });
    const result = {board:[...board], bet, wins, payout:wins.reduce((sum,w) => sum+w.amount,0)};
    return this.applyBonus(result);
  }
  protected applyBonus(result: SpinResult): SpinResult { return result; }
  /** All free spins belong to the original wager and return one settlement result. */
  protected freeSpinSequence(base:SpinResult,next:()=>SpinResult,award:(round:SpinResult)=>number):SpinResult {
    const cap=(round:SpinResult,budget:number)=>{let left=budget;for(const win of round.wins){win.amount=Math.min(left,win.amount);left-=win.amount;}round.payout=budget-left;round.cascades?.forEach(stage=>stage.payout=stage.wins.reduce((n,w)=>n+w.amount,0));return round;};
    cap(base,base.bet*this.maxWin);let remaining=award(base),paid=base.payout;if(!remaining)return base;
    const initialSpins=remaining,rounds=[base];let played=0;
    while(remaining>0&&played<100&&paid<base.bet*this.maxWin){
      remaining--;played++;const round=cap(next(),base.bet*this.maxWin-paid),extra=award(round);paid+=round.payout;remaining=Math.min(100-played,remaining+extra);
      round.roundLabel=`FREE SPINS · ${played}회 · 남은 ${remaining}회`+(extra?` · +${extra}회`:'');rounds.push(round);
    }
    return {freeSpinsAwarded:initialSpins,board:[...rounds[rounds.length-1].board],bet:base.bet,payout:rounds.reduce((n,r)=>n+r.payout,0),wins:rounds.flatMap(r=>r.wins),rounds};
  }
}
