export type LobbyFilter='all'|'favorites'|'popular'|'new';
import {socialSlotCatalog} from '../slots/SocialSlotCatalog';
export const newSlotIds=socialSlotCatalog.map(slot=>slot.id).reverse();
export function filterSlots<T extends {id:string}>(items:T[],filter:LobbyFilter,favorites:string[],plays:Record<string,number>={},unlocked:string[]=[]):T[]{
 if(filter==='favorites')return items.filter(item=>favorites.includes(item.id));
 if(filter==='new')return items.filter(item=>newSlotIds.includes(item.id)).sort((a,b)=>newSlotIds.indexOf(b.id)-newSlotIds.indexOf(a.id));
 if(filter==='popular')return items.filter(item=>(plays[item.id]||0)>0).sort((a,b)=>(plays[b.id]||0)-(plays[a.id]||0));
 return [...items].sort((a,b)=>Number(unlocked.includes(b.id))-Number(unlocked.includes(a.id)));
}
